        self.endCol) = filename, expect, got, begLine, begCol, endLine, endCol

    def __str__(self):
        return ("expected </%s>, got </%s> line: %s col: %s, began line: %s col: %s"
                % (self.expect, self.got, self.endLine, self.endCol, self.begLine,
